// --- 1. 基础哈希算法 (Hash Utils) ---
static inline uint32_t _contract_hash_mix(uint32_t key, uint32_t seed, uint32_t mask) {
    uint32_t h = key ^ seed;
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    h *= 0xc2b2ae35;
    h ^= h >> 16;
    return h & mask;
}

